import unittest


class TestProdSigns(unittest.TestCase):

    def test_empty_array(self):
        self.assertIsNone(prod_signs([]))

    def test_contains_zero(self):
        self.assertEqual(prod_signs([0, 1]), 0)
        self.assertEqual(prod_signs([1, 0, -2, 3]), 0)
        self.assertEqual(prod_signs([0]), 0)

    def test_odd_number_of_negatives(self):
        self.assertEqual(prod_signs([1, 2, 2, -4]), -9)
        self.assertEqual(prod_signs([-1, -2, -3]), -6)
        self.assertEqual(prod_signs([-5]), -5)

    def test_even_number_of_negatives(self):
        self.assertEqual(prod_signs([1, 2, -2, -4]), 9)
        self.assertEqual(prod_signs([-1, -2]), 3)

    def test_all_positive(self):
        self.assertEqual(prod_signs([1, 2, 3]), 6)
        self.assertEqual(prod_signs([5]), 5)

    def test_all_negative(self):
        self.assertEqual(prod_signs([-1, -2, -3, -4]), 10)

    def test_result_matches_expected_formula(self):
        arr = [3, -5, 7, -2]
        expected = (-1) ** len([x for x in arr if x < 0]) * sum(abs(x) for x in arr)
        self.assertEqual(prod_signs(arr), expected)


if __name__ == "__main__":
    unittest.main()
